      SUBROUTINE DECUSE(ERROR)C---- DECODE REFERENCE TO BEAM LINEC-----------------------------------------------------------------------      LOGICAL         ERRORC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'VARY.CIN'C-----------------------------------------------------------------------      CHARACTER*15    KNAME      EQUIVALENCE     (FAKE,LAKE)C-----------------------------------------------------------------------      ERROR = .FALSE.CC---- BEAM LINE NAMEC      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        ERROR = .TRUE.        GO TO 100      ENDIFCC---- STORE REFERENCE TO BEAM LINE TO BE USEDC   60 IF (INDS .EQ. 0 .OR. INSERT) THEN        NUSE = NEL + 1        NDESC = 7        LABLE = KNAME        NWORD = 4        LAKE = 24        DATUM(1) = FAKE        LAKE = 3        DATUM(2) = FAKE        VARY(3) = 100        VARY(4) = 100        CALL ELSTOR      ELSE        LABLE = KNAME        LABEL(NUSE) = LABLE      ENDIFCC---- ACTUAL PARAMETER LISTC      IF (ITEM .EQ. '(') THEN        CALL DECLST      ENDIF  100 RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** BEAM LINE NAME EXPECTED'/' ')  920 FORMAT(' *** ERROR *** UNKNOWN BEAM LINE NAME "',A,'"'/' ')  930 FORMAT(' *** ERROR *** "',A,'" IS NOT A BEAM LINE'/' ')C-----------------------------------------------------------------------      END